record ErrorResponse(int httpLikeStatus, String code, String message) {}

class BoundaryErrorHandler {
    ErrorResponse translate(Exception exception) {
        if (exception instanceof InsufficientFundsException e) {
            return new ErrorResponse(402, "INSUFFICIENT_FUNDS", e.getMessage());
        }
        if (exception instanceof ProductNotFoundException e) {
            return new ErrorResponse(404, "PRODUCT_NOT_FOUND", e.getMessage());
        }
        if (exception instanceof ValidationException e) {
            return new ErrorResponse(400, "VALIDATION_ERROR", e.getMessage());
        }
        return new ErrorResponse(500, "INTERNAL_ERROR", "Wystapil nieoczekiwany blad");
    }
}

class SafeBoundaryErrorHandler {
    ErrorResponse translate(Exception exception) {
        if (isKnownBusinessException(exception)) {
            return mapKnownException(exception); // jak w sekcji CODE_BASIC
        }
        String incidentId = "INC-" + System.currentTimeMillis();
        logFullDetailsInternally(incidentId, exception); // pelny stack trace TYLKO w logu wewnetrznym
        return new ErrorResponse(500, "INTERNAL_ERROR",
            "Wystapil nieoczekiwany blad. ID incydentu: " + incidentId); // zero wewnetrznych detali
    }

    private void logFullDetailsInternally(String incidentId, Exception e) {
        System.err.println("[" + incidentId + "] " + e); // w praktyce: SLF4J/Logback (_16/_13_libraries)
    }

    private boolean isKnownBusinessException(Exception e) { /* ... */ return false; }
    private ErrorResponse mapKnownException(Exception e) { /* ... */ return null; }
}

